WITH matched_keys AS (SELECT status, id FROM accounts EXCEPT ALL SELECT status, id FROM accounts WHERE YEAR(opened_date) >= 2025), kept_rows AS (SELECT s.* FROM accounts s INNER JOIN matched_keys k ON s.status = k.status AND s.id = k.id) SELECT DATE_TRUNC('WEEK', opened_date) AS week_start, COUNT(CASE WHEN account_type = 'LOAN' THEN 1 END) AS loan_count, COUNT(*) FILTER (WHERE account_type = 'CREDIT') AS credit_rows, MAX(balance) FILTER (WHERE account_type = 'CREDIT') AS credit_max_balance, SORT_ARRAY(COLLECT_SET(status)) AS status_list, COUNT(DISTINCT status) AS distinct_status FROM kept_rows GROUP BY week_start;
